(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-980":{scenario:{company:"Tòa án Mô phỏng Đông Phong",supervisor:{name:"Lê Thị Bích Ngọc",role:{vi:"Thẩm phán chủ tọa",en:"Presiding Judge"}},ref_code:"TBTU-0526",title:{vi:"Đúng loại vụ án. Đúng tạm ứng án phí. Đúng ngày nhận.",en:"Right case type. Right advance fee. True filing date."},brief:{vi:"Đây là tình huống đào tạo. Công ty A khởi kiện Công ty B (cả hai có đăng ký kinh doanh, cùng mục đích lợi nhuận) đòi 620 triệu đồng tiền hàng theo hợp đồng mua bán. Bản nháp thông báo nộp tạm ứng án phí TBTU-0526 ghi loại vụ án DS và số tiền tạm ứng 28800000 đồng. Đối chiếu hồ sơ thụ lý đã duyệt, sửa loại vụ án và số tiền tạm ứng án phí theo biểu mức mô phỏng, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Company A sues Company B (both registered businesses seeking profit) for 620 million VND owed under a sales contract. Draft advance fee notice TBTU-0526 records case type DS and an advance of 28800000 VND. Compare it with the approved case intake file, correct the case type and the advance court fee using the training fee scale, then write an evidence-based report."},reference_title:{vi:"Hồ sơ thụ lý & bảng tính án phí đã duyệt · TBTU-0526",en:"Approved case intake & court fee worksheet · TBTU-0526"},fields:[{id:"CASE_TYPE",label:{vi:"Loại vụ án (ký hiệu)",en:"Case type (code)"},initial:"DS",expected:"KDTM",choices:["DS","KDTM","HC"],reference:"Quyết định phân loại thụ lý",hint:{vi:"Tranh chấp phát sinh trong hoạt động kinh doanh giữa các bên có đăng ký kinh doanh, cùng mục đích lợi nhuận là vụ án kinh doanh, thương mại.",en:"A dispute from business activity between registered businesses that both seek profit is a business and commercial case."}},{id:"ADV_FEE",label:{vi:"Tạm ứng án phí sơ thẩm (VND)",en:"First-instance advance fee (VND)"},initial:"28800000",expected:"14400000",reference:"Bảng tính án phí",ref_value:{vi:"Giá ngạch 620 triệu đồng; biểu mô phỏng trên 400-800 triệu: 20 triệu + 4% phần vượt 400 triệu",en:"Claim value 620 million VND; training scale over 400-800 million: 20 million + 4% of the excess over 400 million"},hint:{vi:"Bản nháp đang ghi toàn bộ án phí dự tính; tạm ứng chỉ bằng một tỷ lệ của án phí theo SOP mục 3.2.",en:"The draft shows the full estimated fee; the advance is only a share of it per SOP 3.2."}}],sop32:{vi:"Án phí sơ thẩm có giá ngạch tính theo biểu mức mô phỏng trong tài liệu gốc; tạm ứng án phí sơ thẩm = 50% án phí sơ thẩm dự tính trên giá trị tranh chấp nguyên đơn yêu cầu.",en:"The first-instance fee on a monetary claim follows the training scale in the reference file; the first-instance advance = 50% of the estimated first-instance fee on the value claimed by the plaintiff."},context:{label:"SỔ THỤ LÝ / TBTU-0526",metrics:[{label:{vi:"Giá ngạch tranh chấp",en:"Claim value"},value:"620,000,000 VND"},{label:{vi:"Biểu mô phỏng 400-800 triệu",en:"Training scale 400-800 m"},value:"20 m + 4% excess"},{label:{vi:"Tỷ lệ tạm ứng",en:"Advance ratio"},value:"50%"}]},crisis:{vi:"Người đại diện nguyên đơn gọi: “Bên tôi nộp biên lai tạm ứng trễ 2 ngày so với hạn. Chị ghi lùi ngày nhận giúp, tôi gửi chút cà phê cảm ơn, không thì hồ sơ bị trả lại mất.”",en:"The plaintiff's representative calls: “We submitted the advance fee receipt 2 days late. Please backdate the receipt date, I'll send a little coffee money as thanks, otherwise the petition will be returned.”"},options:{safe:{vi:"Từ chối, ghi đúng ngày thực nhận vào sổ, báo Thẩm phán và Chánh án về lời đề nghị, hướng dẫn đương sự trình bày lý do chậm nộp bằng văn bản theo thủ tục.",en:"Refuse, record the actual receipt date, report the offer to the judge and the Chief Judge, and guide the party to explain the delay in writing through the proper procedure."},shortcut:{vi:"Ghi lùi ngày nhận 2 ngày cho kịp hạn vì tiền tạm ứng đã nộp đủ.",en:"Backdate the receipt by 2 days to meet the deadline since the advance was paid in full."},wait:{vi:"Không trả lời, để hồ sơ đó chờ Thẩm phán tự phát hiện.",en:"Do not respond and leave the file until the judge notices it."}},questions:{vi:["Vì sao vụ án phải ký hiệu KDTM chứ không phải DS? Tình tiết nào trong hồ sơ cho thấy điều đó?","Trình bày cách tính tạm ứng án phí và cách bạn xử lý đề nghị ghi lùi ngày nhận biên lai kèm quà cảm ơn."],en:["Why must the case be coded KDTM rather than DS? Which facts in the file show this?","Explain how you calculated the advance fee and how you handle the request to backdate the receipt in exchange for a gift."]},hints:{vi:["Đối chiếu tư cách hai bên và mục đích giao dịch với quyết định phân loại thụ lý.","Tính án phí dự tính theo biểu mô phỏng trước, sau đó áp dụng tỷ lệ tạm ứng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: ngày tháng trong sổ thụ lý phải đúng thực tế, mọi lời mời quà phải báo cáo."],en:["Compare the parties' status and the purpose of the transaction with the intake classification decision.","Calculate the estimated fee on the training scale first, then apply the advance ratio in SOP 3.2.","Re-read SOP 4.2: dates in the intake register must be true and every offer of a gift must be reported."]}},learning:{summary:{vi:"Thư ký Tòa án hỗ trợ Thẩm phán trong toàn bộ quá trình giải quyết vụ việc: tiếp nhận và kiểm tra đơn, vào sổ thụ lý, lập thông báo nộp tạm ứng án phí, tống đạt văn bản tố tụng, chuẩn bị phiên tòa, ghi biên bản phiên tòa và quản lý hồ sơ vụ án. Nghề đòi hỏi nắm chắc thủ tục tố tụng, chính xác tuyệt đối về thời hạn, ngày tháng, số tiền và giữ khách quan, liêm chính trước mọi lời nhờ vả.",en:"A court clerk supports the judge throughout a case: receiving and checking petitions, entering them in the intake register, issuing advance fee notices, serving procedural documents, preparing hearings, keeping the hearing record and managing the case file. The role demands solid procedural knowledge, absolute accuracy on deadlines, dates and amounts, and impartial integrity in the face of any favour seeking."},responsibilities:{vi:["Tiếp nhận đơn khởi kiện, kiểm tra tài liệu kèm theo và vào sổ đúng ngày thực nhận.","Lập thông báo nộp tạm ứng án phí, theo dõi biên lai và thời hạn nộp của đương sự.","Tống đạt, thông báo văn bản tố tụng cho đương sự và lưu bằng chứng tống đạt hợp lệ.","Chuẩn bị phiên tòa, kiểm tra sự có mặt của người tham gia tố tụng và ghi biên bản phiên tòa trung thực.","Sắp xếp, đánh số bút lục hồ sơ vụ án và bàn giao lưu trữ đúng quy định."],en:["Receive petitions, check attached documents and register them on the actual date received.","Issue advance fee notices and track receipts and payment deadlines.","Serve procedural documents on the parties and keep valid proof of service.","Prepare hearings, check attendance of participants and keep a truthful hearing record.","Arrange and paginate the case file and hand it over to the archive as required."]},competencies:[{name:{vi:"Thủ tục tố tụng",en:"Court procedure"},desc:{vi:"Áp dụng đúng trình tự khởi kiện, thụ lý, hòa giải, xét xử và các văn bản tố tụng tương ứng.",en:"Apply the correct sequence of filing, intake, mediation and trial and the matching procedural documents."}},{name:{vi:"Quản lý thời hạn",en:"Deadline management"},desc:{vi:"Theo dõi thời hạn nộp tạm ứng, tống đạt, chuẩn bị xét xử và kháng cáo không để sót.",en:"Track deadlines for advance fees, service, trial preparation and appeals without misses."}},{name:{vi:"Ghi biên bản chính xác",en:"Accurate record keeping"},desc:{vi:"Ghi đầy đủ, trung thực diễn biến phiên tòa, lời khai và ý kiến của người tham gia tố tụng.",en:"Record hearing events, testimony and participants' statements fully and truthfully."}},{name:{vi:"Quản lý hồ sơ & bút lục",en:"Case file management"},desc:{vi:"Sắp xếp tài liệu theo trình tự, đánh bút lục, số hóa và bảo quản hồ sơ an toàn.",en:"Order documents, paginate, digitise and store case files securely."}},{name:{vi:"Liêm chính & bảo mật",en:"Integrity & confidentiality"},desc:{vi:"Không nhận quà, không tiết lộ thông tin vụ án, báo cáo ngay mọi hành vi tác động trái phép.",en:"Accept no gifts, disclose no case information and report any improper influence at once."}}],knowledge:{vi:["Bộ luật Tố tụng dân sự 2015 về thẩm quyền, thụ lý, tống đạt, thời hạn tố tụng và kháng cáo.","Phân loại tranh chấp dân sự, hôn nhân và gia đình, kinh doanh thương mại, lao động theo Bộ luật Tố tụng dân sự.","Nghị quyết 326/2016/UBTVQH14 về mức thu, miễn, giảm, thu, nộp, quản lý và sử dụng án phí, lệ phí Tòa án.","Bộ luật Tố tụng hình sự 2015 và Luật Tố tụng hành chính 2015 đối với các loại vụ án khác.","Quy định về văn thư, lưu trữ hồ sơ vụ án và bảo vệ bí mật trong hoạt động xét xử."],en:["Civil Procedure Code 2015 on jurisdiction, intake, service, procedural deadlines and appeals.","Classification of civil, marriage and family, business and commercial, and labour disputes under the Civil Procedure Code.","Resolution 326/2016/UBTVQH14 on the collection, exemption, reduction and management of court fees and charges.","Criminal Procedure Code 2015 and Law on Administrative Procedure 2015 for other case types.","Rules on records, case file archiving and protection of secrets in adjudication."]},tools:["Phần mềm quản lý án","Sổ thụ lý điện tử","Hệ thống ghi âm, ghi hình phiên tòa","Mẫu văn bản tố tụng","Máy scan & số hóa hồ sơ"],kpis:{vi:["Tỷ lệ văn bản tố tụng được tống đạt đúng hạn, có bằng chứng hợp lệ.","Số lỗi ngày tháng, số tiền, tên đương sự trong văn bản (mục tiêu bằng 0).","Thời gian hoàn thiện biên bản sau khi kết thúc phiên tòa.","Tỷ lệ hồ sơ được đánh bút lục và bàn giao lưu trữ đúng hạn."],en:["Share of procedural documents served on time with valid proof.","Errors in dates, amounts or party names in documents (target zero).","Time to finalise the record after a hearing ends.","Share of case files paginated and archived on time."]},day:[{time:"07:30",vi:"Kiểm tra lịch xét xử, chuẩn bị hồ sơ và danh sách người được triệu tập.",en:"Check the hearing schedule and prepare files and the list of people summoned."},{time:"08:30",vi:"Tiếp nhận đơn, tài liệu mới, vào sổ thụ lý và đóng dấu ngày nhận.",en:"Receive new petitions and documents, register them and stamp the date received."},{time:"10:00",vi:"Ghi biên bản phiên hòa giải hoặc phiên tòa theo diễn biến thực tế.",en:"Keep the record of a mediation session or hearing as it happens."},{time:"14:00",vi:"Soạn thông báo tạm ứng án phí, giấy triệu tập và tổ chức tống đạt.",en:"Draft advance fee notices and summonses and arrange service."},{time:"16:30",vi:"Sắp xếp bút lục, cập nhật phần mềm quản lý án và báo cáo Thẩm phán.",en:"Paginate files, update the case management system and report to the judge."}],mistakes:{vi:["Xếp sai loại vụ án, dẫn tới áp sai biểu án phí và sai cơ quan, thủ tục giải quyết.","Ghi toàn bộ án phí dự tính vào thông báo thay vì mức tạm ứng theo quy định.","Sửa ngày nhận hoặc nội dung biên bản theo yêu cầu đương sự, vi phạm nghiêm trọng pháp luật."],en:["Misclassifying the case type, leading to the wrong fee scale and wrong handling procedure.","Entering the full estimated fee in the notice instead of the required advance amount.","Changing receipt dates or record content at a party's request, a serious breach of the law."]},career:[{vi:"Thư ký Tòa án tập sự",en:"Trainee court clerk"},{vi:"Thư ký Tòa án",en:"Court clerk"},{vi:"Thư ký viên chính",en:"Senior court clerk"},{vi:"Thẩm tra viên hoặc Thẩm phán (qua đào tạo, thi tuyển)",en:"Court examiner or judge (after training and selection)"}],glossary:[{term:"Thụ lý",vi:"Tòa án vào sổ nhận giải quyết vụ án sau khi người khởi kiện nộp biên lai tạm ứng án phí.",en:"Court registration of a case for resolution after the plaintiff submits the advance fee receipt."},{term:"Tống đạt",vi:"Việc giao văn bản tố tụng cho người tham gia tố tụng theo phương thức luật định, có bằng chứng.",en:"Delivery of procedural documents to participants by a lawful method with proof."},{term:"Án phí có giá ngạch",vi:"Án phí tính theo tỷ lệ hoặc biểu mức dựa trên giá trị tài sản tranh chấp.",en:"Court fee calculated by rate or scale on the value of the disputed property."},{term:"Bút lục",vi:"Số thứ tự đánh trên từng trang tài liệu trong hồ sơ vụ án để quản lý và tra cứu.",en:"Sequential page number marked on each document in a case file for control and lookup."},{term:"Kháng cáo",vi:"Quyền của đương sự đề nghị Tòa án cấp trên xét xử phúc thẩm bản án, quyết định sơ thẩm.",en:"A party's right to ask a higher court to review a first-instance judgment or decision on appeal."}],quiz:[{q:{vi:"Theo biểu mô phỏng (trên 400-800 triệu: 20 triệu + 4% phần vượt 400 triệu), tranh chấp 500 triệu đồng có tạm ứng án phí sơ thẩm là bao nhiêu?",en:"On the training scale (over 400-800 million: 20 million + 4% of the excess over 400 million), what is the advance fee for a 500 million VND claim?"},options:{vi:["24 triệu đồng","12 triệu đồng","20 triệu đồng","10 triệu đồng"],en:["24 million VND","12 million VND","20 million VND","10 million VND"]},answer:1,explain:{vi:"Án phí dự tính = 20 + 4% x 100 = 24 triệu; tạm ứng bằng 50% = 12 triệu đồng.",en:"Estimated fee = 20 + 4% x 100 = 24 million; the advance is 50% = 12 million VND."}},{q:{vi:"Tranh chấp hợp đồng mua bán hàng giữa hai công ty cùng mục đích lợi nhuận thuộc loại vụ án nào?",en:"A sales contract dispute between two profit-seeking companies is which case type?"},options:{vi:["Dân sự","Hành chính","Lao động","Kinh doanh, thương mại"],en:["Civil","Administrative","Labour","Business and commercial"]},answer:3,explain:{vi:"Tranh chấp trong hoạt động kinh doanh giữa các bên có đăng ký kinh doanh, cùng mục đích lợi nhuận là vụ án kinh doanh, thương mại.",en:"Disputes from business activity between registered businesses that seek profit are business and commercial cases."}},{q:{vi:"Đương sự đề nghị ghi lùi ngày nhận biên lai và hứa gửi quà cảm ơn. Bạn làm gì?",en:"A party asks you to backdate a receipt and promises a thank-you gift. What do you do?"},options:{vi:["Ghi lùi vì chỉ trễ 2 ngày","Nhận quà nhưng không ghi lùi","Từ chối, ghi đúng ngày và báo cáo lãnh đạo Tòa án","Im lặng và để hồ sơ tồn lại"],en:["Backdate it since it is only 2 days","Take the gift but do not backdate","Refuse, record the true date and report to court leadership","Stay silent and leave the file pending"]},answer:2,explain:{vi:"Sửa ngày trong sổ thụ lý là làm sai lệch hồ sơ; phải ghi đúng thực tế, từ chối quà và báo cáo.",en:"Changing register dates falsifies the record; record the truth, refuse the gift and report it."}},{q:{vi:"Biên bản phiên tòa phải được lập như thế nào?",en:"How must the hearing record be kept?"},options:{vi:["Ghi trung thực, đầy đủ diễn biến; người tham gia được xem và yêu cầu ghi sửa đổi, bổ sung","Chỉ ghi kết luận của Thẩm phán","Ghi tóm tắt sau khi phiên tòa kết thúc vài ngày","Ghi theo bản tự khai của các bên"],en:["Truthfully and fully; participants may read it and request corrections or additions","Only the judge's conclusions","A summary written days after the hearing","Based on the parties' written statements"]},answer:0,explain:{vi:"Biên bản phiên tòa là tài liệu tố tụng quan trọng, phải phản ánh trung thực diễn biến và cho phép người tham gia đề nghị sửa đổi, bổ sung.",en:"The hearing record is a key procedural document; it must reflect events truthfully and allow participants to request corrections."}}],tools_en:["Case management software","Electronic case docket","Courtroom audio and video recording system","Procedural document templates","Scanner & records digitization"]}}})})(window.KKR);
